import{_ as a,o as t,c as o,ag as n}from"./chunks/framework.8tqBsFWt.js";const p=JSON.parse('{"title":"The Playbook","description":"Named console reads that come back in the same shape every time, so you can watch trends rather than interpret them fresh each week.","frontmatter":{"description":"Named console reads that come back in the same shape every time, so you can watch trends rather than interpret them fresh each week."},"headers":[],"relativePath":"playbook/index.md","filePath":"playbook/index.md"}'),r={name:"playbook/index.md"};function h(i,e,l,s,c,d){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="the-playbook" tabindex="-1">The Playbook <a class="header-anchor" href="#the-playbook" aria-label="Permalink to &quot;The Playbook&quot;">​</a></h1><p>The Playbook is a catalogue of named routines — views and reads you run in the <strong>console</strong>, that come back in the same shape every time.</p><p>These aren&#39;t scripts. Each play shows you the situation, where to go in the console, and what you see when you get there — so you learn the <em>shape</em> of the read, not a sequence of clicks.</p><p>The point is repetition. If the Monday Portfolio Read shows the same columns, in the same order, every Monday, you can watch the trends. That&#39;s what makes this different from a one-off poke at a dashboard. Named. Stable. Repeatable.</p><h2 id="the-shape-stability-contract" tabindex="-1">The shape-stability contract <a class="header-anchor" href="#the-shape-stability-contract" aria-label="Permalink to &quot;The shape-stability contract&quot;">​</a></h2><p>Once a play is published here, its output shape is a contract. Columns, column order, and grouping stay stable across weeks so you can trend the output over time. If a play&#39;s shape needs to change, we version it and note the change at the top of the page.</p><h2 id="plays-by-cadence" tabindex="-1">Plays by cadence <a class="header-anchor" href="#plays-by-cadence" aria-label="Permalink to &quot;Plays by cadence&quot;">​</a></h2><h3 id="daily" tabindex="-1">Daily <a class="header-anchor" href="#daily" aria-label="Permalink to &quot;Daily&quot;">​</a></h3><ul><li><a href="./end-of-day-wrap.html">End-of-day wrap</a> — a team member&#39;s 5pm self-check</li></ul><h3 id="weekly" tabindex="-1">Weekly <a class="header-anchor" href="#weekly" aria-label="Permalink to &quot;Weekly&quot;">​</a></h3><ul><li><a href="./my-week-at-a-glance.html">My week at a glance</a> — a team member&#39;s Monday-morning start</li><li><a href="./monday-portfolio-read.html">Monday portfolio read</a> — the PM&#39;s weekly ritual</li><li><a href="./retainer-burn-check.html">Retainer burn check</a> — is anything quietly losing money?</li><li><a href="./team-availability.html">Team availability for the next two weeks</a> — can we take that new project?</li><li><a href="./ooo-coordination.html">OOO coordination for the week ahead</a> — who&#39;s out and what needs covering?</li></ul><h3 id="monthly" tabindex="-1">Monthly <a class="header-anchor" href="#monthly" aria-label="Permalink to &quot;Monthly&quot;">​</a></h3><ul><li><a href="./month-end-margin-review.html">Month-end margin review</a> — the owner&#39;s P&amp;L read</li><li><a href="./client-summary.html">Client summary for a review meeting</a> — before you sit down with a client</li></ul><h3 id="ad-hoc" tabindex="-1">Ad hoc <a class="header-anchor" href="#ad-hoc" aria-label="Permalink to &quot;Ad hoc&quot;">​</a></h3><ul><li><a href="./project-health-probe.html">Project health probe</a> — one project, everything that matters</li><li><a href="./unresolved-items-sweep.html">Unresolved items sweep</a> — what&#39;s waiting on a decision?</li></ul><h2 id="a-note-on-role-gating" tabindex="-1">A note on role gating <a class="header-anchor" href="#a-note-on-role-gating" aria-label="Permalink to &quot;A note on role gating&quot;">​</a></h2><p>Every play notes who can run it. VERA enforces role permissions at the data layer — a Manager opening a view that includes cost figures simply won&#39;t see those columns. The console adapts to who&#39;s signed in.</p>',17)])])}const y=a(r,[["render",h]]);export{p as __pageData,y as default};
